-- Release the 41 reviewed legacy legal-case backfills plus the separately
-- reviewed specified appeal case. The six blocked legacy cases are intentionally
-- excluded. This migration only adds judgmentDisposition to the existing JSON.

CREATE TEMP TABLE _reviewed_legal_disposition_release (
  claim_id uuid PRIMARY KEY,
  claim_key text NOT NULL,
  person_id uuid NOT NULL,
  source_url text NOT NULL,
  review_status text NOT NULL,
  visibility text NOT NULL,
  is_public boolean NOT NULL,
  disposition jsonb NOT NULL
) ON COMMIT DROP;

