  ('015be61d-3eb7-5268-9f1f-ac95bb87de55', 'council2026:legal-pending:909f10b1a954499b630cdc3c', '96a2a95f-c35b-46e8-8aeb-00c04f794734', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=ULDM%2C113%2C%E7%9F%9A%E8%A8%B4%2C1%2C20250825%2C7', 'verified', 'public', TRUE, '{"text":"沈宗隆共同犯貪污治罪條例之不違背職務收受賄賂罪，處有期徒刑3年6月，褫奪公權8年。已繳交之犯罪所得新臺幣2000萬元沒收。","result":"guilty","section":"主文","version":1,"personId":"96a2a95f-c35b-46e8-8aeb-00c04f794734","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=ULDM%2C113%2C%E7%9F%9A%E8%A8%B4%2C1%2C20250825%2C7","caseNumber":"臺灣雲林地方法院113年度矚訴字第1號","judgmentDate":"2025-08-25","reviewStatus":"reviewed"}'::jsonb),
  ('0666a4aa-f26a-579e-92ea-addb2684d766', 'council2026:legal-pending:411a0de7acd7b4a073c783b2', 'cf7d723a-1e21-4897-bcf2-324c32f63012', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C98%2C%E4%B8%8A%E8%A8%B4%2C4955%2C20110223%2C3', 'verified', 'public', TRUE, '{"text":"原判決撤銷。\n陳漢鍾共同犯交付、收受供偽造有價證券之器械、原料罪，處有期徒刑壹年。","result":"guilty","section":"主文","version":1,"personId":"cf7d723a-1e21-4897-bcf2-324c32f63012","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C98%2C%E4%B8%8A%E8%A8%B4%2C4955%2C20110223%2C3","caseNumber":"臺灣高等法院98年度上訴字第4955號","judgmentDate":"2011-02-23","reviewStatus":"reviewed"}'::jsonb),
  ('149507af-fe5d-50c1-bb51-7274660fe13e', 'council2026:legal-pending:b495cdc309c6571e992d9748', '7fd666f2-3ef8-4732-ad57-7d5f7b233d8b', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=ULDM%2C100%2C%E7%B0%A1%E4%B8%8A%2C108%2C20120131%2C1', 'verified', 'public', TRUE, '{"text":"原判決撤銷。蔡咏鍀犯傷害罪，處有期徒刑參月，如易科罰金，以新臺幣壹仟元折算壹日。","result":"guilty","section":"主文","version":1,"personId":"7fd666f2-3ef8-4732-ad57-7d5f7b233d8b","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=ULDM%2C100%2C%E7%B0%A1%E4%B8%8A%2C108%2C20120131%2C1","caseNumber":"臺灣雲林地方法院100年度簡上字第108號","judgmentDate":"2012-01-31","reviewStatus":"reviewed"}'::jsonb),
  ('16664be1-4e63-5529-80c6-1c6cdbee742d', 'council2026:legal-reviewed:93776d17e2521acd7ec3136c', 'a86bf49e-1d29-43b0-a0d2-bf0e423fd9a2', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C113%2C%E7%9F%9A%E4%B8%8A%E9%87%8D%E8%A8%B4%2C36%2C20251216%2C4', 'verified', 'public', TRUE, '{"text":"原判決關於高虹安、王郁文、黃惠玟及陳奐宇部分撤銷。高虹安共同犯使公務員登載不實罪，處有期徒刑6月，如易科罰金，以新臺幣1仟元折算壹日。","result":"guilty","section":"主文","version":1,"personId":"a86bf49e-1d29-43b0-a0d2-bf0e423fd9a2","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C113%2C%E7%9F%9A%E4%B8%8A%E9%87%8D%E8%A8%B4%2C36%2C20251216%2C4","caseNumber":"臺灣高等法院113年度矚上重訴字第36號","judgmentDate":"2025-12-16","reviewStatus":"reviewed"}'::jsonb),
  ('1841b60d-533d-58e3-989e-bfd038965488', 'council2026:legal-pending:c2ba07d3a5654ce4dc64e303', '6930df6a-6de0-4480-b022-50cf08e21aef', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPSM%2C111%2C%E5%8F%B0%E4%B8%8A%2C787%2C20220519%2C1', 'verified', 'public', TRUE, '{"text":"上訴駁回。","result":"unknown","section":"主文","version":1,"personId":"6930df6a-6de0-4480-b022-50cf08e21aef","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPSM%2C111%2C%E5%8F%B0%E4%B8%8A%2C787%2C20220519%2C1","caseNumber":"最高法院111年度台上字第787號","judgmentDate":"2022-05-19","reviewStatus":"reviewed"}'::jsonb),
  ('28e81dff-64ce-571a-bda0-dc5f5186d033', 'council2026:legal-reviewed:5f6886a6a6491c483395ae41', '54709b82-1761-4aa8-aec2-6a1eb704aef2', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C110%2C%E4%B8%8A%E6%98%93%2C696%2C20210603%2C1', 'verified', 'public', TRUE, '{"text":"原判決撤銷。余筱菁犯散布文字、圖畫誹謗罪，處拘役叁拾日，如易科罰金，以新臺幣壹仟元折算壹日。","result":"guilty","section":"主文","version":1,"personId":"54709b82-1761-4aa8-aec2-6a1eb704aef2","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C110%2C%E4%B8%8A%E6%98%93%2C696%2C20210603%2C1","caseNumber":"臺灣高等法院110年度上易字第696號","judgmentDate":"2021-06-03","reviewStatus":"reviewed"}'::jsonb),
  ('2bc71894-cf00-5b9f-9eae-0ce5c34c909c', 'council2026:legal-pending:a3c07ff9c71247b96e160f82', 'fe9169ae-7876-4554-a7f9-ae336118bd88', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=PCDM%2C110%2C%E8%A8%B4%2C261%2C20250122%2C6', 'verified', 'public', TRUE, '{"text":"曾煥嘉共同犯利用職務上機會詐取財物罪，處有期徒刑參年，褫奪公權肆年。","result":"guilty","section":"主文","version":1,"personId":"fe9169ae-7876-4554-a7f9-ae336118bd88","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=PCDM%2C110%2C%E8%A8%B4%2C261%2C20250122%2C6","caseNumber":"臺灣新北地方法院110年度訴字第261號","judgmentDate":"2025-01-22","reviewStatus":"reviewed"}'::jsonb),
  ('2c9a96d7-7a3c-5b3b-8061-a5769ea21ecd', 'council2026:legal-pending:f95333e5a48ee31eb62ec148', 'f2ad563f-39e9-4748-ad5f-26b678cdf546', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TNHM%2C107%2C%E4%B8%8A%E6%98%93%2C725%2C20181227%2C1', 'verified', 'public', TRUE, '{"text":"上訴駁回。","result":"unknown","section":"主文","version":1,"personId":"f2ad563f-39e9-4748-ad5f-26b678cdf546","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TNHM%2C107%2C%E4%B8%8A%E6%98%93%2C725%2C20181227%2C1","caseNumber":"臺灣高等法院臺南分院107年度上易字第725號","judgmentDate":"2018-12-27","reviewStatus":"reviewed"}'::jsonb),
  ('3c4019a1-0988-5448-bf3e-0eb21bdf1ad9', 'council2026:legal-pending:d05eca52d04170afd938a4ac', '7011d006-03b5-4817-a980-9d78d9727f9b', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPDM%2C113%2C%E9%87%91%E8%A8%B4%2C32%2C20241227%2C3', 'verified', 'public', TRUE, '{"text":"壹、陳重文部分一、陳重文犯如附表甲編號一至六「主文」欄所示之罪，各處如附表甲編號一至六「主文」欄所示之刑。有期徒刑得易科罰金部分（即附表甲編號二、三），應執行有期徒刑陸月，如易科罰金，以新臺幣壹仟元折算壹日；不得易科罰金部分（即附表甲編號一、四、五、六），應執行有期徒刑捌年陸月，褫奪公權陸年。二、未扣案之犯罪所得新臺幣玖拾萬肆仟壹佰貳拾元、肆佰肆拾壹萬元，沒收之，於全部或一部不能沒收或不宜執行沒收時，追徵其價額。三、未扣案之國亨行銷事業有限公司民國一一二年五月二日、一一二年五月十八日股東同意書上偽造「蔡景怡」之署押各壹枚，均沒收。","result":"guilty","section":"主文","version":1,"personId":"7011d006-03b5-4817-a980-9d78d9727f9b","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPDM%2C113%2C%E9%87%91%E8%A8%B4%2C32%2C20241227%2C3","caseNumber":"臺灣臺北地方法院113年度金訴字第32號","judgmentDate":"2024-12-27","reviewStatus":"reviewed"}'::jsonb),
  ('3e47bf42-cf37-5270-8ce5-2b14274bab5a', 'council2026:legal-pending:62d4eca8eecd5f2be9e46f3c', '474fa2e1-9a77-4d32-be7d-0113d7aa1724', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SCDM%2C113%2C%E6%98%93%2C1182%2C20250718%2C1', 'verified', 'public', TRUE, '{"text":"何建樺犯詐欺取財罪，處有期徒刑壹年。緩刑參年。","result":"guilty","section":"主文","version":1,"personId":"474fa2e1-9a77-4d32-be7d-0113d7aa1724","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SCDM%2C113%2C%E6%98%93%2C1182%2C20250718%2C1","caseNumber":"臺灣新竹地方法院113年度易字第1182號","judgmentDate":"2025-07-18","reviewStatus":"reviewed"}'::jsonb),
  ('4b1c356e-2916-502f-b468-9a73af94af63', 'council2026:legal-pending:fc54668cef022423ef3fe43a', '50aebaac-4759-4b53-a13e-07836af138bc', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=KSDM%2c110%2c%e7%b0%a1%e4%b8%8a%2c46%2c20210528%2c1', 'verified', 'public', TRUE, '{"text":"上訴駁回。","result":"unknown","section":"主文","version":2,"personId":"50aebaac-4759-4b53-a13e-07836af138bc","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=KSDM%2c110%2c%e7%b0%a1%e4%b8%8a%2c46%2c20210528%2c1","caseNumber":"臺灣高雄地方法院110年度簡上字第46號","judgmentDate":"2021-05-28","reviewStatus":"reviewed","upheldJudgment":{"prior":{"text":"鄒約翰犯公然侮辱罪，處罰金新臺幣伍仟元，如易服勞役，以新臺幣壹仟元折算壹日。","result":"guilty","section":"主文","version":1,"personId":"50aebaac-4759-4b53-a13e-07836af138bc","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=KSDM%2C109%2C%E7%B0%A1%2C2867%2C20201204%2C1","caseNumber":"臺灣高雄地方法院109年度簡字第2867號","sourceKind":"court_judgment","judgmentDate":"2020-12-04","reviewStatus":"reviewed"},"scope":"entire_person_disposition","personId":"50aebaac-4759-4b53-a13e-07836af138bc","relation":"appeal_dismissed","evidenceText":"臺灣高雄地方法院刑事判決110年度簡上字第46號上訴人即被告鄒約翰上列上訴人即被告因妨害名譽案件，不服本院高雄簡易庭民國109年12月4日109年度簡字第2867號第一審簡易判決（聲請簡易判決處刑案號：109年度偵字第8038號），提起上訴，本院管轄之第二審合議庭判決如下： 前審裁判標題：臺灣高雄地方法院109年度簡字第2867號刑事判決","reviewStatus":"reviewed","priorCaseNumber":"臺灣高雄地方法院109年度簡字第2867號","currentSourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=KSDM%2c110%2c%e7%b0%a1%e4%b8%8a%2c46%2c20210528%2c1","personScopeQuote":"上訴駁回。","currentCaseNumber":"臺灣高雄地方法院110年度簡上字第46號","evidenceSourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=KSDM%2c110%2c%e7%b0%a1%e4%b8%8a%2c46%2c20210528%2c1","currentDispositionText":"上訴駁回。"},"personScopeQuote":"上訴駁回。"}'::jsonb),
  ('4bee1537-2222-5bc8-824b-d017e3fb4133', 'council2026:legal-pending:3337bb5fe1540f7f02002d89', '58ecfe5e-9561-4d9d-baa3-073d90d50492', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=ULDM%2C100%2C%E7%B0%A1%2C50%2C20110922%2C1', 'verified', 'public', TRUE, '{"text":"賴明源共同犯商業會計法第七十一條第一款之填製不實罪，處有期徒刑參月，如易科罰金，以銀元參佰元即新臺幣玖佰元折算壹日，減為有期徒刑壹月又拾伍日，如易科罰金，以銀元參佰元即新臺幣玖佰元折算壹日，緩刑貳年。","result":"guilty","section":"主文","version":1,"personId":"58ecfe5e-9561-4d9d-baa3-073d90d50492","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=ULDM%2C100%2C%E7%B0%A1%2C50%2C20110922%2C1","caseNumber":"臺灣雲林地方法院100年度簡字第50號","judgmentDate":"2011-09-22","reviewStatus":"reviewed"}'::jsonb),
  ('58b7ad62-c320-5cdf-ae05-c79deef64045', 'council2026:legal-pending:b4235e8e87b250a2c609ab1a', 'e53d804a-023f-4cc0-aa69-7d7f5264e74e', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=KMHM%2C90%2C%E4%B8%8A%E6%9B%B4%EF%BC%88%E4%B8%89%EF%BC%89%2C5%2C20020628', 'verified', 'public', TRUE, '{"text":"原判決關於甲○○對於有投票權之人交付賄賂，而約其投票權為一定之行使部分，及丙○○○、陳福海、賴育茜、林登惠、許建中、乙○○、王振權、楊淑媛、趙瑞英部分，均撤銷。\n陳福海、賴育茜、林登惠、許建中、乙○○、王振權、楊淑媛、趙瑞英共同有投票權之人，收受賄賂而許以其投票權為一定之行使，各處有期徒刑拾月，均褫奪公權壹年，所收受之賄賂各新台幣壹佰萬元，應分別與丙○○○連帶沒收之，如全部或一部不能沒收時，應與丙○○○連帶追徵其價額。","result":"guilty","section":"主文","version":1,"personId":"e53d804a-023f-4cc0-aa69-7d7f5264e74e","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=KMHM%2C90%2C%E4%B8%8A%E6%9B%B4%EF%BC%88%E4%B8%89%EF%BC%89%2C5%2C20020628","caseNumber":"福建高等法院金門分院90年度上更（三）字第5號","judgmentDate":"2002-06-28","reviewStatus":"reviewed"}'::jsonb),
  ('5adff6ec-38f9-58ac-b832-35987e28bcb9', 'council2026:legal-pending:2d2fb0a4019d40d26297885d', 'e8adb329-ed35-4d71-bd88-8557bd519a7c', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C100%2C%E4%B8%8A%E8%A8%B4%2C1149%2C20111221%2C1', 'verified', 'public', TRUE, '{"text":"其他上訴駁回。\n黃浴沂、朱瓊純、方簡欽各緩刑叁年，並均應向國庫支付新台幣拾萬元。","result":"unknown","section":"主文","version":1,"personId":"e8adb329-ed35-4d71-bd88-8557bd519a7c","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C100%2C%E4%B8%8A%E8%A8%B4%2C1149%2C20111221%2C1","caseNumber":"臺灣高等法院100年度上訴字第1149號","judgmentDate":"2011-12-21","reviewStatus":"reviewed"}'::jsonb),
  ('5f6407f5-a556-53ce-b236-9d5e7321ef62', 'council2026:legal-reviewed:a6f1b7794b0ae8e41a6ac397', 'a86bf49e-1d29-43b0-a0d2-bf0e423fd9a2', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C113%2C%E4%B8%8A%E8%A8%B4%2C5670%2C20250731%2C1', 'verified', 'public', TRUE, '{"text":"原判決撤銷。高虹安犯誣告罪，處有期徒刑陸月。","result":"guilty","section":"主文","version":1,"personId":"a86bf49e-1d29-43b0-a0d2-bf0e423fd9a2","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C113%2C%E4%B8%8A%E8%A8%B4%2C5670%2C20250731%2C1","caseNumber":"臺灣高等法院113年度上訴字第5670號","judgmentDate":"2025-07-31","reviewStatus":"reviewed"}'::jsonb),
  ('6c6415a6-49f4-5a72-9d31-72af016bc806', 'council2026:legal-pending:16535bb6cc5afb18a88fc2cc', '27229b6b-524e-47f4-8e9a-1fcfe975d014', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=HLHM%2C105%2C%E9%81%B8%E4%B8%8A%E8%A8%B4%2C6%2C20170331%2C1', 'verified', 'public', TRUE, '{"text":"原判決撤銷。\n鍾素政、邱玉林共同預備對於候選人交付賄賂，而約其放棄競選，各處有期徒刑陸月，如易科罰金，均以新臺幣壹仟元折算壹日。各褫奪公權貳年。","result":"guilty","section":"主文","version":1,"personId":"27229b6b-524e-47f4-8e9a-1fcfe975d014","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=HLHM%2C105%2C%E9%81%B8%E4%B8%8A%E8%A8%B4%2C6%2C20170331%2C1","caseNumber":"臺灣高等法院花蓮分院105年度選上訴字第6號","judgmentDate":"2017-03-31","reviewStatus":"reviewed"}'::jsonb),
  ('6c859fea-f833-5980-86e6-54bcbb7b53d6', 'council2026:legal-pending:3fe6d2b9dd6ebcc99b53b42d', '857c36fa-16e1-4c0d-944c-d6bb610bafa5', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TCHM%2C113%2C%E4%B8%8A%E6%9B%B4%E4%B8%80%2C8%2C20240731%2C1', 'verified', 'public', TRUE, '{"text":"原判決關於吳瑞芳宣告刑及定應執行刑部分，均撤銷。 有期徒刑部分，應執行有期徒刑貳年，緩刑伍年，並應於本判決確定後起陸月內，向公庫支付新臺幣壹佰伍拾萬元。","result":"unknown","section":"主文","version":1,"personId":"857c36fa-16e1-4c0d-944c-d6bb610bafa5","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TCHM%2C113%2C%E4%B8%8A%E6%9B%B4%E4%B8%80%2C8%2C20240731%2C1","caseNumber":"臺灣高等法院臺中分院113年度上更一字第8號","judgmentDate":"2024-07-31","reviewStatus":"reviewed"}'::jsonb),
  ('83ef7202-8236-59ee-a9fc-d80726b0c3aa', 'council2026:legal-pending:4de30c2021c3e4702ffff75c', 'f702b00b-3207-41a6-ac72-3e8bcea7a0c9', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TNDM%2C112%2C%E7%B0%A1%2C2371%2C20230725%2C1', 'verified', 'public', TRUE, '{"text":"邱莉莉犯侮辱公務員罪，處拘役參拾日，如易科罰金，以新臺幣壹仟元折算壹日。","result":"guilty","section":"主文","version":1,"personId":"f702b00b-3207-41a6-ac72-3e8bcea7a0c9","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TNDM%2C112%2C%E7%B0%A1%2C2371%2C20230725%2C1","caseNumber":"臺灣臺南地方法院112年度簡字第2371號","judgmentDate":"2023-07-25","reviewStatus":"reviewed"}'::jsonb),
  ('856d75b6-8ab1-523f-9e5d-a4a9cb473e95', 'council2026:legal-pending:c11e15dcf9710254f53c0dc4', '6113380a-8991-4551-b321-f64317e7125f', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C113%2C%E4%B8%8A%E8%A8%B4%2C1784%2C20250227%2C1', 'verified', 'public', TRUE, '{"text":"上訴駁回。","result":"unknown","section":"主文","version":1,"personId":"6113380a-8991-4551-b321-f64317e7125f","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C113%2C%E4%B8%8A%E8%A8%B4%2C1784%2C20250227%2C1","caseNumber":"臺灣高等法院113年度上訴字第1784號","judgmentDate":"2025-02-27","reviewStatus":"reviewed"}'::jsonb),
  ('9ed62e2b-9f21-5348-b1f4-34b1ab13c0f9', 'council2026:legal-pending:d4569a84c16bdf0bf9e86bba', '36190675-6707-48d0-8323-3331771ef0f2', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TCHM%2C99%2C%E9%87%8D%E4%B8%8A%E6%9B%B4%28%E4%BA%8C%29%2C111%2C20111215%2C1', 'verified', 'public', TRUE, '{"text":"原判決關於王瑞麟、吳東昇、洪慶章、蔡慈賢、林明暐、陳聰明、楊騰煌、劉慶發、劉淑芳、陳炳、陳進郎、陳雪鳳、黃秀惠、陳明珠部分，均撤銷。\n劉淑芳共同連續明知為不實之事項，而使公務員登載於職務上所掌之公文書，足以生損害於公眾及他人，處有期徒刑壹年，減為有期徒刑陸月，如易科罰金，以銀元參佰元即新台幣玖佰元折算壹日。","result":"guilty","section":"主文","version":1,"personId":"36190675-6707-48d0-8323-3331771ef0f2","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TCHM%2C99%2C%E9%87%8D%E4%B8%8A%E6%9B%B4%28%E4%BA%8C%29%2C111%2C20111215%2C1","caseNumber":"臺灣高等法院臺中分院99年度重上更（二）字第111號","judgmentDate":"2011-12-15","reviewStatus":"reviewed"}'::jsonb),
  ('abcfc485-2016-5e65-9756-4a46c8d699b3', 'council2026:legal-pending:b7e3107ecec387265031eff0', '7011d006-03b5-4817-a980-9d78d9727f9b', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SLDM%2C115%2C%E5%AF%A9%E9%81%B8%E7%B0%A1%2C1%2C20260313%2C1', 'verified', 'public', TRUE, '{"text":"陳思宗、陳重文共同犯農會法第四十七條之一第一項第二款之交付財物罪，各處有期徒刑伍月，如易科罰金，均以新臺幣壹仟元折算壹日。","result":"guilty","section":"主文","version":1,"personId":"7011d006-03b5-4817-a980-9d78d9727f9b","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SLDM%2C115%2C%E5%AF%A9%E9%81%B8%E7%B0%A1%2C1%2C20260313%2C1","caseNumber":"臺灣士林地方法院115年度審選簡字第1號","judgmentDate":"2026-03-13","reviewStatus":"reviewed"}'::jsonb),
  ('ac7bf5c0-93ce-5dee-b2a3-ee919c177064', 'council2026:legal-reviewed:082c5d56ef65513ccb2b84fc', '427c9f8a-fc88-4be4-a2db-941822ae0a45', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SLDM%2C114%2C%E8%A8%B4%2C629%2C20260112%2C2', 'verified', 'public', TRUE, '{"text":"一、陳怡君共同犯利用職務機會詐取財物罪，處有期徒刑參年拾月，褫奪公權伍年。又共同犯利用職務機會詐取財物罪，處有期徒刑參年捌月，褫奪公權伍年。又共同犯不違背職務收受賄賂罪，處有期徒刑參年拾月，褫奪公權伍年。應執行有期徒刑柒年拾月，褫奪公權伍年。","result":"guilty","section":"主文","version":1,"personId":"427c9f8a-fc88-4be4-a2db-941822ae0a45","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SLDM%2C114%2C%E8%A8%B4%2C629%2C20260112%2C2","caseNumber":"臺灣士林地方法院114年度訴字第629號","judgmentDate":"2026-01-12","reviewStatus":"reviewed"}'::jsonb),
  ('b4d48290-c6af-5c1f-aa56-7da56f12cf0d', 'council2026:legal-pending:abee81cc34e035d11a83831a', 'af8d759a-1b06-408b-9db9-d0c2d0880ea7', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=KSDM%2C101%2C%E6%98%93%2C228%2C20121031%2C5', 'verified', 'public', TRUE, '{"text":"陳麗娜犯公務員洩漏國防以外之秘密文書罪，處有期徒刑伍月，如易科罰金，以新臺幣壹仟元折算壹日。","result":"guilty","section":"主文","version":1,"personId":"af8d759a-1b06-408b-9db9-d0c2d0880ea7","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=KSDM%2C101%2C%E6%98%93%2C228%2C20121031%2C5","caseNumber":"臺灣高雄地方法院101年度易字第228號","judgmentDate":"2012-10-31","reviewStatus":"reviewed"}'::jsonb),
  ('bc36512f-3da9-5783-80c6-ba450ed8fc98', 'council2026:legal-pending:4f2add392cd88da18a1602ba', '36da2f57-032b-4077-842f-5ec691ffcb4c', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C114%2C%E4%B8%8A%E6%98%93%2C7%2C20250515%2C1', 'verified', 'public', TRUE, '{"text":"上訴駁回。","result":"unknown","section":"主文","version":1,"personId":"36da2f57-032b-4077-842f-5ec691ffcb4c","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TPHM%2C114%2C%E4%B8%8A%E6%98%93%2C7%2C20250515%2C1","caseNumber":"臺灣高等法院114年度上易字第7號","judgmentDate":"2025-05-15","reviewStatus":"reviewed"}'::jsonb),
  ('bdb011ce-c6a6-557a-8257-a453f9dd52c4', 'council2026:legal-pending:c4c9501d7567dc600785890f', '6daac75e-813f-4114-a5ff-9d1a97fc68cf', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SCDM%2C112%2C%E8%A8%B4%2C578%2C20250430%2C2', 'verified', 'public', TRUE, '{"text":"黃文政犯利用職務機會詐取財物罪，共貳罪，各處有期徒刑壹年捌月，各褫奪公權貳年。應執行有期徒刑貳年，褫奪公權貳年。緩刑伍年，並應於本案判決確定後壹年內，向公庫支付新臺幣參拾萬元。","result":"guilty","section":"主文","version":1,"personId":"6daac75e-813f-4114-a5ff-9d1a97fc68cf","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SCDM%2C112%2C%E8%A8%B4%2C578%2C20250430%2C2","caseNumber":"臺灣新竹地方法院112年度訴字第578號","judgmentDate":"2025-04-30","reviewStatus":"reviewed"}'::jsonb),
  ('bf49d289-b945-55c9-b269-244674c58f87', 'council2026:legal-reviewed:b1e34ab6e530b521c1dfca3b', '2f3e0b50-725e-43c7-aef3-939bbce505b0', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TCHM%2c110%2c%e5%8e%9f%e9%81%b8%e4%b8%8a%e8%a8%b4%2c1%2c20211124%2c1', 'verified', 'public', TRUE, '{"text":"上訴駁回。","result":"unknown","section":"主文","version":2,"personId":"2f3e0b50-725e-43c7-aef3-939bbce505b0","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TCHM%2c110%2c%e5%8e%9f%e9%81%b8%e4%b8%8a%e8%a8%b4%2c1%2c20211124%2c1","caseNumber":"臺灣高等法院臺中分院110年度原選上訴字第1號","judgmentDate":"2021-11-24","reviewStatus":"reviewed","upheldJudgment":{"prior":{"text":"王春梅共同犯對於有投票權人預備交付賄賂罪，處有期徒刑拾月。褫奪公權壹年。","result":"guilty","section":"主文","version":1,"personId":"2f3e0b50-725e-43c7-aef3-939bbce505b0","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TCDM%2C109%2C%E5%8E%9F%E9%81%B8%E8%A8%B4%2C1%2C20210311%2C1","caseNumber":"臺灣臺中地方法院109年度原選訴字第1號","sourceKind":"court_judgment","judgmentDate":"2021-03-11","reviewStatus":"reviewed"},"scope":"entire_person_disposition","personId":"2f3e0b50-725e-43c7-aef3-939bbce505b0","relation":"appeal_dismissed","evidenceText":"臺灣高等法院臺中分院刑事判決110年度原選上訴字第1號上訴人臺灣臺中地方檢察署檢察官上訴人即被告王春梅送達代收人徐嘉欣選任辯護人羅閎逸律師陳瑞斌律師上訴人即被告忠仁‧達祿斯選任辯護人李永裕律師陳忠儀律師彭祐宸律師上列上訴人因被告違反公職人員選舉罷免法案件，不服臺灣臺中地方法院109年度原選訴字第1號，中華民國110年3月11日第一審判決（起訴案號：臺灣臺中地方檢察署109年度選偵字第30、57號），提起上訴，本院判決如下： 前審裁判標題：臺灣臺中地方法院109年度原選訴字第1號刑事判決","reviewStatus":"reviewed","priorCaseNumber":"臺灣臺中地方法院109年度原選訴字第1號","currentSourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TCHM%2c110%2c%e5%8e%9f%e9%81%b8%e4%b8%8a%e8%a8%b4%2c1%2c20211124%2c1","personScopeQuote":"上訴駁回。","currentCaseNumber":"臺灣高等法院臺中分院110年度原選上訴字第1號","evidenceSourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TCHM%2c110%2c%e5%8e%9f%e9%81%b8%e4%b8%8a%e8%a8%b4%2c1%2c20211124%2c1","currentDispositionText":"上訴駁回。"},"personScopeQuote":"上訴駁回。"}'::jsonb),
  ('bff877f5-534a-5332-87c0-8e0f65e1f5e0', 'council2026:legal-reviewed:e15d855081e7fcf238bda7bf', '6e7d2c4c-966f-44d1-a8f5-118c0574b7f0', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SCDM%2C113%2C%E8%A8%B4%2C83%2C20250318%2C1', 'verified', 'public', TRUE, '{"text":"一、陳治雄共同利用職務機會詐取財物罪，共肆罪，各處有期徒刑壹年拾月，均褫奪公權肆年。應執行有期徒刑貳年，褫奪公權肆年。緩刑伍年，並應於檢察官指定之期間內向公庫支付新臺幣參拾萬元。扣案之犯罪所得新臺幣貳佰柒拾玖萬零肆佰零壹元沒收。","result":"guilty","section":"主文","version":1,"personId":"6e7d2c4c-966f-44d1-a8f5-118c0574b7f0","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=SCDM%2C113%2C%E8%A8%B4%2C83%2C20250318%2C1","caseNumber":"臺灣新竹地方法院113年度訴字第83號","judgmentDate":"2025-03-18","reviewStatus":"reviewed"}'::jsonb),
  ('caa0bf1d-ed8e-50f3-8edb-5a422cfc6cfa', 'council2026:legal-pending:60f2d931669f4d26628a61ea', '7dda3f82-9377-4ecc-a9aa-74b7397533c4', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=PTDM%2C112%2C%E6%98%93%2C526%2C20240221%2C1', 'verified', 'public', TRUE, '{"text":"方冠丁犯誹謗罪，處拘役伍拾玖日，如易科罰金，以新臺幣壹仟元折算壹日。","result":"guilty","section":"主文","version":1,"personId":"7dda3f82-9377-4ecc-a9aa-74b7397533c4","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=PTDM%2C112%2C%E6%98%93%2C526%2C20240221%2C1","caseNumber":"臺灣屏東地方法院112年度易字第526號","judgmentDate":"2024-02-21","reviewStatus":"reviewed"}'::jsonb),
  ('ce0a32cc-e95a-5163-a871-c671ce8a36dc', 'council2026:legal-pending:89311d100c31cc631a4d4131', 'db9df2fa-aee6-42bd-bd40-9f2eb50dec99', 'https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TYDM%2C112%2C%E9%81%B8%E8%A8%B4%2C12%2C20250930%2C2', 'verified', 'public', TRUE, '{"text":"一、郭麗華共同犯總統副總統選舉罷免法第八十七條第一項第二款之對連署人交付賄賂使其為特定被連署人連署罪，處有期徒刑參年拾月，併科罰金新臺幣參佰萬元，罰金如易服勞役，以罰金總額與壹年之日數比例折算。褫奪公權伍年。","result":"guilty","section":"主文","version":1,"personId":"db9df2fa-aee6-42bd-bd40-9f2eb50dec99","sourceUrl":"https://judgment.judicial.gov.tw/FJUD/data.aspx?ty=JD&id=TYDM%2C112%2C%E9%81%B8%E8%A8%B4%2C12%2C20250930%2C2","caseNumber":"臺灣桃園地方法院112年度選訴字第12號","judgmentDate":"2025-09-30","reviewStatus":"reviewed"}'::jsonb),
